<script setup lang="ts">import {computed,ref} from 'vue';import {Result} from '../types/domain';import {number} from '../utils/format';import DataTable from './common/DataTable.vue';const props=defineProps<{result:Result}>();const focus=ref('');const pairwise=computed(()=>props.result.pairwise);const hasPairs=computed(()=>!!pairwise.value&&pairwise.value.pairs.length>0);const pairs=computed(()=>pairwise.value?.pairs||[]);const key=(a:string,b:string)=>a+'|'+b;function prob(v:number|null){return v==null?'不可检验':number(v,4)}</script><template><section class="pairwise-tests"><template v-if="pairwise"><div class="section-heading"><h2>全部工艺对检验</h2><span>{{pairwise.method_label}} / 运行级校正 / 同时纳入{{pairwise.testable_pairs}}个可检验对</span></div><template v-if="hasPairs"><div class="run-picker"><label>聚焦查看工艺对<select aria-label="聚焦工艺对" :value="focus" @change="focus=($event.target as HTMLSelectElement).value"><option value="">全部工艺对（校正范围不变）</option><option v-for="p in pairs" :key="key(p.group_a,p.group_b)" :value="key(p.group_a,p.group_b)">{{p.group_a}} vs {{p.group_b}}</option></select></label></div><DataTable :head="['工艺对','样本数','R²','原始p','校正后p','校正排名','可检验性']"><tr v-for="p in pairs" :key="key(p.group_a,p.group_b)" :class="{selected:focus===key(p.group_a,p.group_b)}"><td><b>{{p.group_a}} vs {{p.group_b}}</b><small>独立置换 / 对种子 {{p.pair_seed}}</small></td><td>{{p.n_a}} / {{p.n_b}}<small>合计 {{p.n}}</small></td><td>{{p.testable?number(p.R2,5):'—'}}</td><td>{{prob(p.p_raw)}}</td><td>{{prob(p.p_adjusted)}}</td><td>{{p.testable?p.rank:'不参与排序'}}</td><td :class="p.testable?'':'warning'">{{p.testable?'可检验':p.reason}}</td></tr></DataTable><p class="pairwise-note">{{pairwise.correction_scope}} {{pairwise.note}}</p><p class="pairwise-note">每对只使用该对两组样本，对各自派生种子独立置换标签；原始p与校正后p同时保留。聚焦查看只改变高亮，不重算也不缩小校正范围。全局p回答“是否存在组差”，不能指出哪两个工艺不同。</p></template><p v-else-if="pairwise.legacy" class="pending-inline">历史运行未保存工艺对检验（{{pairwise.note}}）。</p><p v-else class="pending-inline">该运行没有工艺对结果。</p></template><p v-else class="pending-inline">该运行早于工艺对检验版本，只保留全局PERMANOVA。</p></section></template>
